const { createHash, randomUUID } = require('crypto');
const input = $input.first().json;
const sha256 = (value) => createHash('sha256').update(value, 'utf8').digest('hex');
const generatedAt = new Date().toISOString();
const correlationId = randomUUID();
const runId = randomUUID();
const inputHash = `sha256:${sha256(JSON.stringify(input))}`;
const idempotencySource = [input.tenant_id, 'WF-00', input.source_event_id, input.purpose, '1.0.0'].join('|');
return [{ json: { schema_version: '1.0.0', message_id: randomUUID(), trace_id: randomUUID(), causation_id: null, run_id: runId, correlation_id: correlationId, producer_version: 'wf-00@0.1.0', generated_at: generatedAt, input_hash: inputHash, idempotency_key: `sha256:${sha256(idempotencySource)}`, policy_snapshot: { routing: 'draft-0.1.0', data_access: 'draft-0.1.0', autonomy_budget: 'draft-0.1.0' }, release_id: 'offline-dev-0.1.0', execution_mode: 'OFFLINE_EVAL', external_effects_allowed: false, event: { event_id: randomUUID(), tenant_id: input.tenant_id, received_at: input.received_at, source: input.source, source_event_id: input.source_event_id, actor_id: input.actor_id, subject_ref: input.subject_ref, purpose: input.purpose, data_classification: input.data_classification }, payload: { text: input.text } } }];

const { randomUUID } = require('crypto');
const envelope = $input.first().json;
const text = String(envelope.payload?.text ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const domainRules = [
  { domain: 'conta', capabilities: ['resolver_identidade', 'avaliar_elegibilidade'], terms: ['cadastro', 'cnpj', 'conta', 'limite', 'elegibilidade', 'documento'] },
  { domain: 'performance', capabilities: ['avaliar_performance', 'identificar_gap_execucao'], terms: ['meta', 'pobj', 'producao', 'pontuacao', 'prazo', 'performance'] },
  { domain: 'financeiro', capabilities: ['calcular_rentabilidade', 'avaliar_viabilidade'], terms: ['rentabilidade', 'margem', 'receita', 'custo', 'financeiro', 'retorno'] },
  { domain: 'relacionamento', capabilities: ['recuperar_contexto', 'preparar_abordagem'], terms: ['conversa', 'reuniao', 'relacionamento', 'cliente', 'compromisso', 'abordagem'] }
];
const fullView = text.includes('visao 360') || text.includes('360 completa');
const selected = domainRules.filter((rule) => fullView || rule.terms.some((term) => text.includes(term))).map(({ domain, capabilities }) => ({ domain, requirement: 'REQUIRED', capabilities }));
const selectedNames = new Set(selected.map((item) => item.domain));
const excluded = domainRules.filter((rule) => !selectedNames.has(rule.domain)).map((rule) => ({ domain: rule.domain, reason_code: 'NOT_REQUIRED_FOR_INTENT' }));
const needsReview = selected.length === 0;
return [{ json: { ...envelope, routing: { schema_version: '1.0.0', routing_id: randomUUID(), routing_method: 'DETERMINISTIC', rule_id: fullView ? 'routing.full_view.v1' : 'routing.keyword.v1', routing_confidence: null, intent: fullView ? 'visao_executiva_completa' : 'triagem_por_capacidade', selected_domains: selected, excluded_domains: excluded, dependencies: [{ before: 'identity_resolution', after: 'domain_consolidation' }], execution_mode: 'PARALLEL_WHEN_INDEPENDENT', fallback: 'MANUAL_REVIEW_REQUIRED', decision_status: needsReview ? 'MANUAL_REVIEW_REQUIRED' : 'READY' }, manual_review: needsReview ? { reason_code: 'ROUTING_AMBIGUOUS', problem_statement: 'A regra determinística não identificou um domínio necessário.', impact: 'O fluxo não pode delegar com segurança.', required_decision: 'Classificar a finalidade e selecionar as capacidades necessárias.', owner_queue: 'REVISAO_DIRETOR_360' } : null } }];

const output = $input.first().json;
const required = ['schema_version', 'message_id', 'trace_id', 'run_id', 'correlation_id', 'producer_version', 'generated_at', 'input_hash', 'idempotency_key', 'policy_snapshot', 'release_id', 'event', 'routing'];
const missing = required.filter((field) => output[field] === undefined || output[field] === null);
if (missing.length) throw new Error(`Contrato inválido; campos ausentes: ${missing.join(', ')}`);
if (output.execution_mode !== 'OFFLINE_EVAL' || output.external_effects_allowed !== false) throw new Error('Este workflow só pode operar em OFFLINE_EVAL sem efeitos externos');
if (output.routing.decision_status === 'READY' && output.routing.selected_domains.length === 0) throw new Error('READY exige pelo menos um domínio selecionado');
return [{ json: { ...output, validation: { structural: 'VALID', semantic: 'VALID', validated_at: new Date().toISOString(), next_component: output.routing.decision_status === 'READY' ? 'GENERAL_MANAGERS' : 'CENTRAL_REVISAO_360' }, execution_status: output.routing.decision_status === 'READY' ? 'ROUTED' : 'MANUAL_REVIEW_REQUIRED' } }];
